import { MediaGrid, Card } from "march/ui"

// gezi albümü: dört fotoğraf kare ızgarada; dokununca hangisi açıldı yazılır
const photos = ["sunset", "sea", "forest", "city"].map((n) => ({ src: `/media/social/${n}.svg`, alt: n }))

export function TripAlbum() {
  let $open = "—"
  return <Card m:theme="night">
    <MediaGrid items={photos} gap="gap" onOpen={(i: number) => $open = photos[i]!.alt} />
    <span sx={{ text: "sm", color: "muted" }}>Açılan: {$open}</span>
  </Card>
}

import { MediaGrid, Segmented } from "march/ui"

// gönderi fotoğrafları: sayı seçilir, 1, 2, 3 ve 4+ için ayrı yerleşim; fazlası +N
const all = ["sunset", "sea", "forest", "city", "coffee", "ride"].map((n) => ({ src: `/media/social/${n}.svg`, alt: n }))

export function PostPhotos() {
  let $n = "3"
  return <div sx={{ flex: "col", gap: 2 }}>
    <Segmented aria-label="Fotoğraf" value={$n} options={["1", "2", "3", "4", "6"]} onChange={(v: string) => $n = v} />
    {() => <MediaGrid items={all.slice(0, Number($n))} />}
  </div>
}

import { MediaGrid } from "march/ui"

// MediaGrid'in özellikleri: items (src, alt, kind, poster, width, height), max, shape, gap, onOpen, onDoubleTap, label,
// tileLabel, skeleton, videoMark, more, class
const items = [
  { src: "/media/social/sunset.svg", alt: "Gün batımı", width: 1200, height: 1500 },
  { src: "/media/social/sea.svg", alt: "Deniz", kind: "video" as const, poster: "/media/social/sea.svg" },
  { src: "/media/social/forest.svg", alt: "Orman" },
  { src: "/media/social/city.svg", alt: "Şehir" },
  { src: "/media/social/coffee.svg", alt: "Kahve" },
]

export function MediaGridLab() {
  let $log = "—"
  return <div sx={{ flex: "col", gap: 2 }}>
    <MediaGrid class="lab-grid" items={items} max={3} shape="square" gap="thin" label="Gezi" skeleton={false}
      tileLabel={(i: number, n: number) => `Fotoğraf ${i + 1} / ${n}`} videoMark more={(rest: number) => `+${rest} daha`}
      onOpen={(i: number) => $log = `açıldı ${i}`} onDoubleTap={(i: number) => $log = `beğenildi ${i}`} />
    <span class="lab-log">{$log}</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { MediaGridLab } from "./MediaGridLab.tsx"

// MediaGridLab'in testleri: kaydedince Testler sekmesinde çalışır
test("ızgara adını label'dan alır, fazlası kendi metniyle", () => {
  const s = renderTest(() => <MediaGridLab />)
  expect(s.get(".lab-grid")?.getAttribute("aria-label")).toBe("Gezi")
  expect(s.get(".lab-grid")?.textContent).toContain("daha")
})

test("tileLabel kutuların adını verir, basınca onOpen", async () => {
  const s = renderTest(() => <MediaGridLab />)
  await s.click("Fotoğraf 1 / 5")
  await s.flush(3)
  expect(s.get(".lab-log")?.textContent).toContain("0")
})
